/*
 * 07_word_search.c — find a word in a letter grid by walking adjacent cells
 *
 * Concept : Backtracking on a grid: from each start cell, DFS in 4 directions
 *           matching the word letter by letter. The state to undo is the
 *           "visited" mark (a cell may be used only once per path). We mark
 *           in place by overwriting the letter with '#' and restore it on the
 *           way back — no extra visited[][] array.
 *           Self-check: (1) hand-picked words with known answers, (2) every
 *           found path is re-validated, (3) random words generated by random
 *           SIMPLE walks on the grid must always be found.
 * Build   : make run P=dsa/15-recursion-and-backtracking/c/07_word_search.c
 * Read    : ../README.md  (section "Word search")
 */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define R 4
#define C 5
static char grid[R][C + 1] = {
    "ABCEX",
    "SFCSY",
    "ADEEZ",
    "QRTUV",
};

static int path_r[R * C], path_c[R * C];         /* the cells of the match */
static long calls;

/*
 * Search for "SEE" starting at (1,3) 'S':
 *
 *   A B C E X        match S at (1,3), mark '#'
 *   S F C # Y        neighbours: up (0,3)='E' ok -> mark, need 'E' next:
 *   A D E E Z           its neighbours: (0,2)C (0,4)X (1,3)# -> all fail
 *   Q R T U V           -> UNMARK (0,3), try down (2,3)='E' -> mark,
 *                         need 'E': (2,2)='E' -> FOUND "SEE"
 *
 * Without the unmark step, (0,3) would stay '#' and later searches would
 * wrongly fail: forgetting the un-choose is THE classic backtracking bug.
 */
static int dfs(int r, int c, const char *w, int k)
{
    ++calls;
    if (w[k] == '\0') return 1;                         /* matched everything */
    if (r < 0 || r >= R || c < 0 || c >= C) return 0;   /* off the grid       */
    if (grid[r][c] != w[k]) return 0;                   /* wrong letter or '#' */
    char saved = grid[r][c];
    grid[r][c] = '#';                                   /* CHOOSE: mark used  */
    path_r[k] = r; path_c[k] = c;
    int found = dfs(r + 1, c, w, k + 1) || dfs(r - 1, c, w, k + 1)
             || dfs(r, c + 1, w, k + 1) || dfs(r, c - 1, w, k + 1);
    grid[r][c] = saved;                                 /* UN-CHOOSE: restore */
    return found;
}

static int exist(const char *w)
{
    /* Cheap pruning before any search: the grid must contain enough copies
       of every letter. Kills hopeless words in O(R*C + len). */
    int have[256] = {0}, need[256] = {0};
    for (int r = 0; r < R; ++r) for (int c = 0; c < C; ++c) ++have[(unsigned char)grid[r][c]];
    for (const char *p = w; *p; ++p) if (++need[(unsigned char)*p] > have[(unsigned char)*p]) return 0;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c)
            if (dfs(r, c, w, 0)) return 1;
    return 0;
}

static void check_path(const char *w)
{
    int len = (int)strlen(w);
    for (int k = 0; k < len; ++k) {
        assert(grid[path_r[k]][path_c[k]] == w[k]);            /* letters   */
        if (k) assert(abs(path_r[k] - path_r[k - 1]) + abs(path_c[k] - path_c[k - 1]) == 1);
        for (int j = 0; j < k; ++j)                             /* no reuse  */
            assert(path_r[j] != path_r[k] || path_c[j] != path_c[k]);
    }
}

int main(void)
{
    char before[R][C + 1];
    memcpy(before, grid, sizeof grid);

    struct { const char *w; int expect; } cases[] = {
        { "ABCCED", 1 }, { "SEE", 1 }, { "ABCB", 0 },   /* ABCB reuses B */
        { "A", 1 }, { "XYZV", 1 }, { "QRTUVZYX", 1 },
        { "AQD", 0 }, { "ZZ", 0 }, { "ESCE", 1 }, { "SFDA", 1 },
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i) {
        calls = 0;
        int got = exist(cases[i].w);
        printf("  %-10s -> %s  (%ld dfs calls)\n", cases[i].w, got ? "found" : "absent", calls);
        assert(got == cases[i].expect);
        if (got) check_path(cases[i].w);
        assert(memcmp(before, grid, sizeof grid) == 0);   /* grid fully restored */
    }

    /* Random simple walks -> their spelling must be found. */
    srand(15);
    for (int t = 0; t < 2000; ++t) {
        int seen[R][C] = {{0}};
        char w[R * C + 1];
        int r = rand() % R, c = rand() % C, len = 0, target = 1 + rand() % 8;
        seen[r][c] = 1; w[len++] = grid[r][c];
        while (len < target) {
            static const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
            int opts[4], no = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !seen[nr][nc]) opts[no++] = d;
            }
            if (!no) break;
            int d = opts[rand() % no];
            r += dr[d]; c += dc[d]; seen[r][c] = 1; w[len++] = grid[r][c];
        }
        w[len] = '\0';
        assert(exist(w));
        check_path(w);
    }
    assert(memcmp(before, grid, sizeof grid) == 0);
    printf("2000 random simple-walk words all found with valid paths\n");

    printf("\nall word-search checks passed\n");
    return 0;
}
